CREATE TABLE IF NOT EXISTS `{prefix}_autopost_queue` ( `id` int(11) NOT NULL AUTO_INCREMENT, `news_id` int(11) NOT NULL, `target` varchar(20) NOT NULL DEFAULT 'all', `status` enum('pending','processing','failed','done') NOT NULL DEFAULT 'pending', `attempts` tinyint(3) NOT NULL DEFAULT 0, `error_message` text, `created_at` datetime NOT NULL, `updated_at` datetime NOT NULL, PRIMARY KEY (`id`), KEY `status` (`status`), KEY `news_id` (`news_id`) ) ENGINE={engine} DEFAULT CHARSET={charset};
CREATE TABLE IF NOT EXISTS `{prefix}_autopost_log` ( `id` int(11) NOT NULL AUTO_INCREMENT, `news_id` int(11) NOT NULL, `channel` enum('telegram','vk') NOT NULL, `remote_id` varchar(100) DEFAULT NULL, `status` enum('success','error') NOT NULL, `error_message` text, `post_date` datetime NOT NULL, PRIMARY KEY (`id`), KEY `news_id` (`news_id`), KEY `status` (`status`) ) ENGINE={engine} DEFAULT CHARSET={charset};
INSERT IGNORE INTO `{prefix}_admin_sections` (`name`, `title`, `descr`, `icon`, `allow_groups`) VALUES ('autopost', 'Автопостинг VK & Telegram', 'Публикация пресс-релизов и новостей в соцсети', 'autopost.png', '1');

