dleplugin.phpuninstall:
@unlink(ENGINE_DIR . '/data/autopost.php');
$dir = ENGINE_DIR . '/classes/autopost';
if (is_dir($dir)) {
	$files = glob($dir . '/*');
	if ($files) {
		foreach ($files as $f) {
			if (is_file($f)) @unlink($f);
		}
	}
	@rmdir($dir);
}

